'use client'

import { useEffect, useMemo, useState } from 'react'
import { AlertTriangle, ArrowDownToLine, ArrowUpFromLine, CalendarDays, ClipboardList, LayoutDashboard, Menu, Package, Plus, Search, Trash2, X } from 'lucide-react'
import { createClient } from '@/lib/supabase/client'

type Product = { id: string; name: string; category: string; unit: string; current: number; minimum: number; ideal: number }
type StockUser = { id: string; name: string; username?: string; active: boolean; auth_user_id?: string }
type Movement = { id: string; productId: string; type: 'Entrada' | 'Saída'; quantity: number; date: string; userId?: string; notes?: string }
type PurchaseItem = { id: string; productId: string; quantity: number }
type PurchaseOrder = { id: string; createdAt: string; status: 'criado' | 'recebido' | 'cancelado'; items: PurchaseItem[] }

const categories = ['Saladas e Frutas', 'Mercearia e Secos', 'Congelados e Prontos', 'Carnes e Laticínios', 'Limpeza', 'Embalagens', 'Bebidas Bar', 'Bebidas Salão']
const initialProducts: Product[] = [
  { id: 'idalfaceamericana1', name: 'Alface americana', category: 'Saladas e Frutas', unit: 'cx', current: 12, minimum: 4, ideal: 20 },
  { id: 'idtomatelongavida2', name: 'Tomate longa vida', category: 'Saladas e Frutas', unit: 'cx', current: 8, minimum: 3, ideal: 15 },
  { id: 'idcebola5', name: 'Cebola', category: 'Saladas e Frutas', unit: 'kg', current: 18, minimum: 8, ideal: 30 },
  { id: 'idovos16', name: 'Ovos', category: 'Mercearia e Secos', unit: 'cartela', current: 10, minimum: 4, ideal: 18 },
  { id: 'idoleodesoja17', name: 'Óleo de soja', category: 'Mercearia e Secos', unit: 'cx', current: 6, minimum: 3, ideal: 12 },
  { id: 'idbatata', name: 'Batata frita congelada', category: 'Congelados e Prontos', unit: 'pct', current: 22, minimum: 8, ideal: 40 },
  { id: 'idqueijo', name: 'Queijo mussarela', category: 'Carnes e Laticínios', unit: 'kg', current: 9, minimum: 4, ideal: 16 },
  { id: 'idheineken', name: 'Heineken 600ml', category: 'Bebidas Bar', unit: 'un', current: 40, minimum: 30, ideal: 200 },
  { id: 'idcoca', name: 'Coca-Cola', category: 'Bebidas Bar', unit: 'un', current: 18, minimum: 24, ideal: 60 },
  { id: 'idgelo', name: 'Gelo', category: 'Bebidas Bar', unit: 'saco', current: 3, minimum: 6, ideal: 15 },
  { id: 'idcopo', name: 'Copo descartável 300ml', category: 'Embalagens', unit: 'pct', current: 14, minimum: 5, ideal: 25 },
  { id: 'idmultiuso', name: 'Desinfetante', category: 'Limpeza', unit: 'un', current: 7, minimum: 3, ideal: 12 },
]

const today = () => new Date().toISOString()
const formatDate = (date: string) => new Date(date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })

export default function Page() {
  const [products, setProducts] = useState<Product[]>(initialProducts)
  const [movements, setMovements] = useState<Movement[]>([])
  const [stockUsers, setStockUsers] = useState<StockUser[]>([])
  const [currentUserId, setCurrentUserId] = useState('')
  const [view, setView] = useState('dashboard')
  const [menuOpen, setMenuOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('')
  const [productsCategory, setProductsCategory] = useState('Todas as categorias')
  const [selectedProduct, setSelectedProduct] = useState('')
  const [quantity, setQuantity] = useState('')
  const [movementNotes, setMovementNotes] = useState('')
  const [movementSaving, setMovementSaving] = useState(false)
  const [quickActionProduct, setQuickActionProduct] = useState<Product | null>(null)
  const [editing, setEditing] = useState<Product | null>(null)
  const [toast, setToast] = useState('')
  const [historyFilter, setHistoryFilter] = useState('Todos')
  const [historyFiltersOpen, setHistoryFiltersOpen] = useState(false)
  const [historyPeriod, setHistoryPeriod] = useState('Todos')
  const [historyUser, setHistoryUser] = useState('Todos')
  const [historyCategory, setHistoryCategory] = useState('Todas')
  const [historyProduct, setHistoryProduct] = useState('')
  const [historyStart, setHistoryStart] = useState('')
  const [historyEnd, setHistoryEnd] = useState('')
  const [orders, setOrders] = useState<PurchaseOrder[]>([])
  const [selectedOrder, setSelectedOrder] = useState<string | null>(null)
  const [purchaseQuantities, setPurchaseQuantities] = useState<Record<string, number>>({})
  const [purchaseCategory, setPurchaseCategory] = useState('Todas as categorias')
  const [purchaseDays, setPurchaseDays] = useState<number[]>([1, 4])
  const [authUser, setAuthUser] = useState<{ id: string; recordId: string; name: string; username: string } | null>(null)
  const [authLoading, setAuthLoading] = useState(true)
  const [hasUsers, setHasUsers] = useState(true)
  const [authMode, setAuthMode] = useState<'welcome' | 'login' | 'create'>('welcome')

  useEffect(() => {
    const supabase = createClient()
    void supabase.auth.getUser().then(async ({ data }) => { const rows = await fetch('/api/stock-users').then((response) => response.ok ? response.json() : []); setHasUsers(rows.length > 0); const user = data.user; const profile = user ? rows.find((row: { auth_user_id?: string }) => row.auth_user_id === user.id) : null; setAuthUser(user && profile ? { id: user.id, recordId: profile.id, name: profile.name, username: profile.username } : null); setAuthMode(rows.length ? 'login' : 'welcome'); setAuthLoading(false) })
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => { if (!session?.user) setAuthUser(null) })
    return () => listener.subscription.unsubscribe()
  }, [])

  useEffect(() => { if (authUser) setCurrentUserId(authUser.id) }, [authUser])

  useEffect(() => {
    if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => undefined)
    const supabase = createClient()
    void Promise.all([
      supabase.from('stock_products').select('id,name,category,unit,current_quantity,minimum_quantity,ideal_quantity').order('name'),
      supabase.from('stock_movements').select('id,product_id,movement_type,quantity,movement_date,user_id,usuario_id,notes').order('movement_date', { ascending: true }),
      supabase.from('stock_users').select('id,name,username,active,auth_user_id').eq('active', true).order('name'),
      supabase.from('pedidos_compra').select('id,data_criacao,status').order('data_criacao', { ascending: false }),
    ]).then(async ([productResult, movementResult, usersResult, orderResult]) => {
      if (productResult.error || movementResult.error) return
      const databaseProducts = productResult.data ?? []
      if (!databaseProducts.length) {
        const { error: seedError } = await supabase.from('stock_products').upsert(initialProducts.map((p) => ({ id: p.id, name: p.name, category: p.category, unit: p.unit, current_quantity: p.current, minimum_quantity: p.minimum, ideal_quantity: p.ideal })))
        if (seedError) {
          console.error('[v0] Erro ao carregar produtos iniciais:', seedError)
          setToast(`Erro ao carregar produtos: ${seedError.message}`)
          return
        }
        setProducts(initialProducts)
      } else {
        setProducts(databaseProducts.map((p) => ({ id: p.id, name: p.name, category: p.category, unit: p.unit, current: p.current_quantity, minimum: p.minimum_quantity, ideal: p.ideal_quantity })))
      }
      setMovements((movementResult.data ?? []).map((m) => ({ id: m.id, productId: m.product_id, type: m.movement_type as Movement['type'], quantity: m.quantity, date: m.movement_date, userId: m.user_id, notes: m.notes })))
      setStockUsers((usersResult.data ?? []).map((u) => ({ id: u.id, name: u.name, username: u.username, active: u.active, auth_user_id: u.auth_user_id })))
      if (!orderResult.error) {
        const orderRows = orderResult.data ?? []
        const itemResult = await supabase.from('itens_pedido_compra').select('id,pedido_id,produto_id,quantidade').in('pedido_id', orderRows.map((o) => o.id))
        const itemsByOrder = new Map<string, PurchaseItem[]>()
        ;(itemResult.data ?? []).forEach((item) => itemsByOrder.set(item.pedido_id, [...(itemsByOrder.get(item.pedido_id) ?? []), { id: item.id, productId: item.produto_id, quantity: item.quantidade }]))
        setOrders(orderRows.map((o) => ({ id: o.id, createdAt: o.data_criacao, status: o.status, items: itemsByOrder.get(o.id) ?? [] })))
      }
    })
  }, [])
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 2600); return () => clearTimeout(t) } }, [toast])

  const lowStock = products.filter((p) => p.current <= p.minimum)
  const lowByCategory = Array.from(new Set(lowStock.map((p) => p.category))).map((category) => ({ category, count: lowStock.filter((p) => p.category === category).length })).sort((a, b) => b.count - a.count)
  const shoppingList = products.filter((p) => p.current <= p.minimum && p.ideal > p.current).map((p) => ({ ...p, suggested: p.ideal - p.current }))
  const todayWeekday = new Date().getDay()
  const isPurchaseDay = purchaseDays.includes(todayWeekday === 0 ? 7 : todayWeekday)
  const weekMovements = movements.filter((m) => Date.now() - new Date(m.date).getTime() <= 7 * 86400000)
  const filteredProducts = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()))
  const visibleMovements = movements.filter((m) => { const product = products.find((p) => p.id === m.productId); const age = Date.now() - new Date(m.date).getTime(); const periodOk = historyPeriod === 'Todos' || (historyPeriod === 'Hoje' && age <= 86400000) || (historyPeriod === '7' && age <= 7 * 86400000) || (historyPeriod === '30' && age <= 30 * 86400000) || (historyPeriod === 'Personalizado' && (!historyStart || new Date(m.date) >= new Date(`${historyStart}T00:00:00`)) && (!historyEnd || new Date(m.date) <= new Date(`${historyEnd}T23:59:59`))); return (historyFilter === 'Todos' || m.type === historyFilter) && periodOk && (historyUser === 'Todos' || m.userId === historyUser || m.userId === stockUsers.find((u) => u.auth_user_id === historyUser)?.id) && (historyCategory === 'Todas' || product?.category === historyCategory) && (!historyProduct || product?.name.toLowerCase().includes(historyProduct.toLowerCase())) }).slice().reverse()

  async function registerMovement(type: 'Entrada' | 'Saída') {
    if (movementSaving) return
    if (!authUser) return setToast('Faça login para registrar movimentações.')
    const amount = Number(quantity)
    const product = products.find((p) => p.id === selectedProduct)
    if (!product || !Number.isInteger(amount) || amount <= 0) return setToast('Informe um produto e uma quantidade válida.')
    if (!movementNotes.trim()) return setToast('Informe uma observação para continuar.')
    if (type === 'Saída' && amount > product.current) return setToast('A saída não pode deixar o estoque negativo.')
    const normalizedNotes = movementNotes.trim()
    const recentDuplicate = movements.some((movement) => movement.productId === product.id && movement.userId === authUser.recordId && movement.type === type && movement.quantity === amount && movement.notes?.trim() === normalizedNotes && Date.now() - new Date(movement.date).getTime() < 10000)
    if (recentDuplicate) return setToast('Esta movimentação já foi registrada.')
    const supabase = createClient()
    const duplicateSince = new Date(Date.now() - 10000).toISOString()
    const { data: databaseDuplicates, error: duplicateError } = await supabase.from('stock_movements').select('id').eq('product_id', product.id).eq('user_id', authUser.recordId).eq('usuario_id', authUser.id).eq('movement_type', type).eq('quantity', amount).eq('notes', normalizedNotes).gte('movement_date', duplicateSince).limit(1)
    if (duplicateError) return setToast(`Erro ao validar movimentação: ${duplicateError.message}`)
    if (databaseDuplicates?.length) return setToast('Esta movimentação já foi registrada.')
    const nextQuantity = type === 'Entrada' ? product.current + amount : product.current - amount
    setMovementSaving(true)
    const movementId = crypto.randomUUID()
    const movementDate = today()
    const { error: movementError } = await supabase.from('stock_movements').insert({ id: movementId, product_id: product.id, movement_type: type, quantity: amount, movement_date: movementDate, user_id: authUser.recordId, usuario_id: authUser.id, notes: normalizedNotes })
    if (movementError) {
      console.error('[v0] Erro ao inserir movimentação:', movementError)
      setMovementSaving(false)
      return setToast(`Erro ao salvar movimentação: ${movementError.message}`)
    }
    const { error: productError } = await supabase.from('stock_products').update({ current_quantity: nextQuantity, updated_at: movementDate }).eq('id', product.id)
    if (productError) {
      console.error('[v0] Erro ao atualizar estoque:', productError)
      await supabase.from('stock_movements').delete().eq('id', movementId)
      setMovementSaving(false)
      return setToast(`Erro ao atualizar estoque: ${productError.message}`)
    }
    setProducts((current) => current.map((p) => p.id === product.id ? { ...p, current: nextQuantity } : p))
    setMovements((current) => [...current, { id: movementId, productId: product.id, type, quantity: amount, date: movementDate, userId: authUser.recordId, notes: normalizedNotes }])
  setMovementNotes('')
    setQuantity(''); setSelectedProduct(''); setQuickActionProduct(null); setMovementSaving(false); setToast(`${type} registrada para ${product.name}.`)
  }
  async function saveProduct() { if (!editing?.name.trim()) return; const supabase = createClient(); const payload = { id: editing.id, name: editing.name.trim(), category: editing.category, unit: editing.unit.trim(), current_quantity: editing.current, minimum_quantity: editing.minimum, ideal_quantity: editing.ideal, updated_at: today() }; const { error } = await supabase.from('stock_products').upsert(payload); if (error) return setToast('Não foi possível salvar o produto.'); setProducts((current) => current.some((p) => p.id === editing.id) ? current.map((p) => p.id === editing.id ? editing : p) : [...current, editing]); setEditing(null); setToast('Produto atualizado com sucesso') }
  async function removeProduct(id: string) { const { error } = await createClient().from('stock_products').delete().eq('id', id); if (error) return setToast('Não foi possível remover o produto.'); setProducts((current) => current.filter((p) => p.id !== id)); setMovements((current) => current.filter((m) => m.productId !== id)); setToast('Produto removido.') }
  async function confirmPurchase(items: Array<{ productId: string; quantity: number }>) {
    const validItems = items.filter((item) => Number.isInteger(item.quantity) && item.quantity > 0)
    if (!validItems.length) return setToast('Informe ao menos uma quantidade para comprar.')
    const supabase = createClient()
    const orderId = crypto.randomUUID()
    const createdAt = today()
    const { error: orderError } = await supabase.from('pedidos_compra').insert({ id: orderId, data_criacao: createdAt, status: 'criado' })
    if (orderError) return setToast('Não foi possível criar o pedido.')
    const rows = validItems.map((item) => ({ id: crypto.randomUUID(), pedido_id: orderId, produto_id: item.productId, quantidade: item.quantity }))
    const { error: itemError } = await supabase.from('itens_pedido_compra').insert(rows)
    if (itemError) { await supabase.from('pedidos_compra').delete().eq('id', orderId); return setToast('Não foi possível salvar os itens do pedido.') }
    setOrders((current) => [{ id: orderId, createdAt, status: 'criado', items: rows.map((row) => ({ id: row.id, productId: row.produto_id, quantity: row.quantidade })) }, ...current])
    setPurchaseQuantities({})
    setToast(`Pedido criado com sucesso · ${orderId.slice(0, 8).toUpperCase()}`)
  }
  function go(viewName: string, category?: string) { setView(viewName); if (viewName === 'products' && category) setProductsCategory(category); if (viewName === 'entry') { setSelectedCategory(category ?? ''); setSelectedProduct(''); setQuantity(''); setQuickActionProduct(null) } setMenuOpen(false) }

  if (authLoading) return <div className="auth-loading">Carregando sessão…</div>
  if (!authUser) { if (authMode === 'welcome') return <WelcomeScreen hasUsers={hasUsers} onLogin={() => setAuthMode('login')} onCreate={() => setAuthMode('create')} />; if (authMode === 'create') return <CreateUserScreen onBack={() => setAuthMode(hasUsers ? 'login' : 'welcome')} onCreated={() => { setHasUsers(true); setAuthMode('login') }} />; return <LoginScreen onLogin={setAuthUser} onCreate={() => setAuthMode('create')} /> }

  return <div className="app-shell">
    <header className="topbar"><div className="brand">Estoque <span>Vai Mais BG</span></div><button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label={menuOpen ? 'Fechar menu' : 'Abrir menu'} aria-expanded={menuOpen}><Menu size={22} /></button><div className="top-date">Olá, {authUser.name} · {new Date().toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: 'short' })}</div><button className="logout-button" onClick={() => void createClient().auth.signOut()}>Sair</button></header>
    {menuOpen && <button className="drawer-scrim" aria-label="Fechar menu" onClick={() => setMenuOpen(false)} />}
    <nav className={`nav ${menuOpen ? 'open' : ''}`} aria-label="Navegação principal">{[['dashboard', 'Dashboard', LayoutDashboard], ['products', 'Produtos', Package], ['entry', 'Entrada de estoque', ArrowDownToLine], ['exit', 'Registrar saída', ArrowUpFromLine], ['history', 'Histórico', ClipboardList], ['purchase', 'Lista de compras', AlertTriangle], ['orders', 'Pedidos de compra', ClipboardList], ['users', 'Usuários', ClipboardList]].map(([key, label, Icon]) => <button key={key as string} className={view === key ? 'active' : ''} onClick={() => go(key as string)}><Icon size={19} />{label as string}</button>)}</nav>
    <main className="content">{view === 'dashboard' && <Dashboard products={products} lowStock={lowStock} lowByCategory={lowByCategory} shoppingList={shoppingList} isPurchaseDay={isPurchaseDay} movements={movements} onNavigate={go} />}
      {view === 'products' && <><PageTitle title="Produtos" subtitle={`${products.length} produtos cadastrados`} action={<div className="title-actions"><button className="primary" onClick={() => setEditing({ id: crypto.randomUUID(), name: '', category: categories[0], unit: 'un', current: 0, minimum: 0, ideal: 0 })}><Plus size={17} /> Novo produto</button></div>} /><div className="search"><Search size={17} /><input placeholder="Buscar produto ou categoria" value={query} onChange={(e) => setQuery(e.target.value)} /></div><ProductCategoryView products={products} selected={productsCategory} onSelect={setProductsCategory} query={query} onEdit={setEditing} /></>}
      {(view === 'entry' || view === 'exit') && <CategoryMovementForm users={stockUsers} currentUserId={currentUserId} setCurrentUserId={setCurrentUserId} type={view === 'entry' ? 'Entrada' : 'Saída'} products={products} category={selectedCategory} selected={selectedProduct} quantity={quantity} setCategory={(value) => { setSelectedCategory(value); setSelectedProduct('') }} setSelected={setSelectedProduct} setQuantity={setQuantity} notes={movementNotes} setNotes={setMovementNotes} submit={registerMovement} onSelectProduct={setQuickActionProduct} />}
      {view === 'history' && <><PageTitle title="Histórico de movimentações" subtitle="Entradas e saídas registradas" action={<button className="secondary filter-toggle" onClick={() => setHistoryFiltersOpen(!historyFiltersOpen)}><Search size={16} />Filtros</button>} />{historyFiltersOpen && <section className="history-filters"><div className="filter-grid"><label>Período<select value={historyPeriod} onChange={(e) => setHistoryPeriod(e.target.value)}><option value="Todos">Todos</option><option value="Hoje">Hoje</option><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="Personalizado">Personalizado</option></select></label><label>Tipo<select value={historyFilter} onChange={(e) => setHistoryFilter(e.target.value)}><option>Todos</option><option>Entrada</option><option>Saída</option></select></label><label>Responsável<select value={historyUser} onChange={(e) => setHistoryUser(e.target.value)}><option value="Todos">Todos</option>{stockUsers.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label><label>Categoria<select value={historyCategory} onChange={(e) => setHistoryCategory(e.target.value)}><option>Todas</option>{categories.map((category) => <option key={category}>{category}</option>)}</select></label><label className="filter-product">Produto<input value={historyProduct} onChange={(e) => setHistoryProduct(e.target.value)} placeholder="Pesquisar produto" /></label>{historyPeriod === 'Personalizado' && <><label>Data inicial<input type="date" value={historyStart} onChange={(e) => setHistoryStart(e.target.value)} /></label><label>Data final<input type="date" value={historyEnd} onChange={(e) => setHistoryEnd(e.target.value)} /></label></>}</div><button className="text-button" onClick={() => { setHistoryFilter('Todos'); setHistoryPeriod('Todos'); setHistoryUser('Todos'); setHistoryCategory('Todas'); setHistoryProduct(''); setHistoryStart(''); setHistoryEnd('') }}>Limpar filtros</button></section>}<div className="history-list">{visibleMovements.length ? visibleMovements.map((m) => { const product = products.find((p) => p.id === m.productId); const user = stockUsers.find((u) => u.id === m.userId || u.auth_user_id === m.userId); return <div className="history-row history-detail" key={m.id}><span className={`movement-dot ${m.type === 'Entrada' ? 'in' : 'out'}`}>{m.type === 'Entrada' ? '+' : '−'}</span><div><strong>{product?.name ?? 'Produto removido'}</strong><small>{m.type} · {new Date(m.date).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}</small><small>Quantidade: {m.quantity} {product?.unit ?? 'un.'} · Responsável: {user?.name ?? 'Usuário não identificado'}</small>{m.notes && <small>Observação: {m.notes}</small>}</div></div> }) : <Empty text="Nenhuma movimentação encontrada com estes filtros." />}</div></>}
      {view === 'purchase' && <ShoppingList products={shoppingList} category={purchaseCategory} setCategory={setPurchaseCategory} quantities={purchaseQuantities} setQuantities={setPurchaseQuantities} confirm={confirmPurchase} purchaseDays={purchaseDays} setPurchaseDays={setPurchaseDays} />}
      {view === 'orders' && <Orders orders={orders} products={products} selectedOrder={selectedOrder} setSelectedOrder={setSelectedOrder} />}
      {view === 'users' && <Users users={stockUsers} setUsers={setStockUsers} currentUserId={authUser.id} />}
    </main>
    {quickActionProduct && <QuickMovementModal type={view === 'entry' ? 'Entrada' : 'Saída'} product={quickActionProduct} quantity={quantity} setQuantity={setQuantity} notes={movementNotes} setNotes={setMovementNotes} saving={movementSaving} submit={registerMovement} close={() => { setQuickActionProduct(null); setSelectedProduct(''); setQuantity(''); setMovementNotes('') }} />}
    {editing && <ProductModal product={editing} setProduct={setEditing} save={saveProduct} remove={products.some((p) => p.id === editing.id) ? () => { removeProduct(editing.id); setEditing(null) } : undefined} />}
    {toast && <div className="toast">{toast}</div>}
  </div>
}

function WelcomeScreen({ hasUsers, onLogin, onCreate }: { hasUsers: boolean; onLogin: () => void; onCreate: () => void }) { return <main className="auth-screen"><section className="auth-card welcome-card"><p className="eyebrow">Estoque Vai Mais BG</p><h1>Controle seu estoque com clareza.</h1><p>{hasUsers ? 'Entre para continuar no painel de estoque.' : 'Crie o primeiro usuário para começar.'}</p><div className="auth-actions"><button className="primary" onClick={onLogin}>Entrar</button><button className="secondary" onClick={onCreate}>Criar usuário</button></div></section></main> }

function LoginScreen({ onLogin, onCreate }: { onLogin: (user: { id: string; recordId: string; name: string; username: string }) => void; onCreate: () => void }) { const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(''); const rows = await fetch('/api/stock-users').then((response) => response.json()); const profile = rows.find((row: { username?: string }) => row.username === username.trim().toLowerCase()); const { data, error: authError } = profile ? await createClient().auth.signInWithPassword({ email: `${username.trim().toLowerCase()}@vaimaisbg.com`, password }) : { data: { user: null }, error: new Error('invalid') }; setBusy(false); if (authError || !data.user || !profile) return setError('Usuário ou senha inválidos.'); onLogin({ id: data.user.id, recordId: profile.id, name: profile.name, username: profile.username }) }; return <main className="auth-screen"><form className="auth-card" onSubmit={submit}><p className="eyebrow">Estoque Vai Mais BG</p><h1>Acesso ao estoque</h1><p>Entre com seu usuário e senha para continuar.</p><label>Usuário<input type="text" value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" required /></label><label>Senha<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" required /></label>{error && <div className="auth-error" role="alert">{error}</div>}<button className="primary" disabled={busy}>{busy ? 'Entrando…' : 'Entrar'}</button><button type="button" className="text-button" onClick={onCreate}>Criar usuário</button></form></main> }

function CreateUserScreen({ onBack, onCreated }: { onBack: () => void; onCreated: () => void }) { const [form, setForm] = useState({ name: '', username: '', password: '', confirm: '' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const submit = async (event: React.FormEvent) => { event.preventDefault(); setError(''); if (form.password.length < 6) return setError('A senha precisa ter pelo menos 6 caracteres.'); if (form.password !== form.confirm) return setError('As senhas não conferem.'); setBusy(true); const response = await fetch('/api/stock-users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: form.name, username: form.username, password: form.password }) }); const data = await response.json(); setBusy(false); if (!response.ok) return setError(data.error ?? 'Erro desconhecido ao criar usuário.'); onCreated() }; return <main className="auth-screen"><form className="auth-card" onSubmit={submit}><button type="button" className="back-button" onClick={onBack}>Voltar</button><p className="eyebrow">Estoque Vai Mais BG</p><h1>Criar usuário</h1><p>Cadastre o acesso para começar a usar o estoque.</p><label>Nome<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Nome de usuário<input value={form.username} onChange={(event) => setForm({ ...form, username: event.target.value.toLowerCase() })} autoComplete="username" required /></label><label>Senha<input type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required /></label><label>Confirmar senha<input type="password" value={form.confirm} onChange={(event) => setForm({ ...form, confirm: event.target.value })} required /></label>{error && <div className="auth-error" role="alert">{error}</div>}<button className="primary" disabled={busy}>{busy ? 'Salvando…' : 'Salvar usuário'}</button></form></main> }

function Users({ users, setUsers, currentUserId }: { users: StockUser[]; setUsers: (users: StockUser[]) => void; currentUserId: string }) { const [form, setForm] = useState({ name: '', username: '', password: '' }); const [editing, setEditing] = useState<StockUser & { username?: string; auth_user_id?: string } | null>(null); const [confirming, setConfirming] = useState<StockUser & { username?: string; auth_user_id?: string } | null>(null); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const save = async () => { const target = editing ? { ...editing, ...form } : form; const response = await fetch('/api/stock-users', { method: editing ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(editing ? { ...target, id: editing.id, auth_user_id: editing.auth_user_id } : target) }); const data = await response.json(); if (!response.ok) return setError(data.error ?? 'Não foi possível salvar o usuário.'); setUsers([...users.filter((user) => user.id !== data.id), data].sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'))); setForm({ name: '', username: '', password: '' }); setEditing(null) }; const remove = async () => { if (!confirming) return; setError(''); const response = await fetch('/api/stock-users', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id: confirming.id }) }); const data = await response.json(); if (!response.ok) return setError(data.error ?? 'Não foi possível excluir o usuário.'); setUsers(users.filter((user) => user.id !== confirming.id)); setConfirming(null); setMessage('Usuário excluído com sucesso'); setTimeout(() => setMessage(''), 3000) }; return <><PageTitle title="Usuários" subtitle="Cadastre e edite os acessos do estoque" />{message && <div className="success-message" role="status">{message}</div>}{error && <div className="auth-error" role="alert">{error}</div>}<div className="user-create"><input placeholder="Nome" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /><input placeholder="Usuário" value={form.username} onChange={(event) => setForm({ ...form, username: event.target.value })} /><input placeholder={editing ? 'Nova senha (opcional)' : 'Senha'} type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} /><button className="primary" onClick={save}>{editing ? 'Salvar alteração' : 'Cadastrar usuário'}</button></div><div className="user-list">{users.length ? users.map((user) => <div className="user-row" key={user.id}><button className="user-edit-trigger" onClick={() => { setEditing(user as StockUser & { username?: string; auth_user_id?: string }); setForm({ name: user.name, username: (user as StockUser & { username?: string }).username ?? '', password: '' }) }}><strong>{user.name}</strong><span>{user.username ?? 'Sem login'}</span></button><button className="delete-user-button" disabled={user.auth_user_id === currentUserId || user.id === currentUserId || users.length <= 1} onClick={() => setConfirming(user as StockUser & { username?: string; auth_user_id?: string })}>Excluir usuário</button></div>) : <Empty text="Nenhum usuário cadastrado ainda." />}</div>{confirming && <div className="modal-backdrop" role="presentation"><section className="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="delete-user-title"><h2 id="delete-user-title">Tem certeza que deseja excluir este usuário?</h2><dl><dt>Nome do usuário</dt><dd>{confirming.name}</dd><dt>Nome de login</dt><dd>{confirming.username ?? 'Sem login'}</dd></dl><div className="modal-actions"><button className="secondary" onClick={() => setConfirming(null)}>Cancelar</button><button className="danger-button" onClick={remove}>Excluir</button></div></section></div>}</> }

function PageTitle({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className="page-title"><div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div> }
function Empty({ text }: { text: string }) { return <div className="empty">{text}</div> }
function Dashboard({ products, lowStock, lowByCategory, shoppingList, isPurchaseDay, movements, onNavigate }: { products: Product[]; lowStock: Product[]; lowByCategory: Array<{ category: string; count: number }>; shoppingList: Array<Product & { suggested: number }>; isPurchaseDay: boolean; movements: Movement[]; onNavigate: (v: string, category?: string) => void }) { const recent = movements.slice(-4).reverse(); return <><PageTitle title="Olá, equipe 👋" subtitle="Visão rápida do estoque" />{isPurchaseDay && shoppingList.length > 0 && <button className="shopping-day-banner" onClick={() => onNavigate('purchase')}><CalendarDays size={20} /><span><strong>Lista de compras disponível</strong><small>{shoppingList.length} {shoppingList.length === 1 ? 'produto precisa' : 'produtos precisam'} de reposição hoje.</small></span><b>Ver lista →</b></button>}<div className="stats"><button onClick={() => onNavigate('products')}><Package /><b>{products.length}</b><span>Produtos</span></button><button className={lowStock.length ? 'warning' : ''} onClick={() => onNavigate('products')}><AlertTriangle /><b>{lowStock.length}</b><span>Estoque baixo</span></button><button onClick={() => onNavigate('history')}><ArrowUpFromLine /><b>{movements.filter((m) => Date.now() - new Date(m.date).getTime() < 7 * 86400000).reduce((sum, m) => sum + (m.type === 'Saída' ? m.quantity : 0), 0)}</b><span>Consumo na semana</span></button></div>{lowByCategory.length > 0 && <section className="alert-card"><div className="section-heading"><h2>Estoque baixo por categoria</h2><button onClick={() => onNavigate('purchase')}>Ver sugestão</button></div>{lowByCategory.map((item) => <button className="alert-row category-alert-row" key={item.category} onClick={() => onNavigate('entry', item.category)}><span><i className="stock-status-dot critical" />{item.category}</span><b>{item.count} {item.count === 1 ? 'produto precisa' : 'produtos precisam'} atenção</b></button>)}</section>}<section className="quick-actions"><h2>Ações rápidas</h2><div><button onClick={() => onNavigate('entry')}><ArrowDownToLine />Entrada</button><button onClick={() => onNavigate('exit')}><ArrowUpFromLine />Registrar saída</button></div></section><section><div className="section-heading"><h2>Últimas movimentações</h2><button onClick={() => onNavigate('history')}>Ver histórico</button></div>{recent.length ? recent.map((m) => <div className="history-row compact" key={m.id}><span className={`movement-dot ${m.type === 'Entrada' ? 'in' : 'out'}`}>{m.type === 'Entrada' ? '+' : '−'}</span><div><strong>{products.find((p) => p.id === m.productId)?.name}</strong><small>{m.type} · {formatDate(m.date)}</small></div><b>{m.quantity}</b></div>) : <Empty text="As movimentações aparecerão aqui." />}</section></> }
function ProductCategoryView({ products, selected, onSelect, query, onEdit }: { products: Product[]; selected: string; onSelect: (category: string) => void; query: string; onEdit: (product: Product) => void }) { const categoryNames = Array.from(new Set(products.map((p) => p.category))).sort((a, b) => a.localeCompare(b, 'pt-BR')); const normalizedQuery = query.trim().toLowerCase(); const matches = (p: Product) => !normalizedQuery || p.name.toLowerCase().includes(normalizedQuery) || p.category.toLowerCase().includes(normalizedQuery); const visible = products.filter((p) => (selected === 'Todas as categorias' || p.category === selected) && matches(p)); const statusFor = (p: Product) => p.current <= p.minimum ? { label: 'Abaixo do mínimo', tone: 'critical' } : p.current <= p.minimum * 1.25 ? { label: 'Próximo do mínimo', tone: 'attention' } : { label: 'Estoque normal', tone: 'normal' }; return <>{!normalizedQuery && selected === 'Todas as categorias' ? <div className="category-grid product-category-grid"><button type="button" className="category-card all-categories selected" onClick={() => onSelect('Todas as categorias')}><Package size={22} /><div><strong>Todas as categorias</strong><small>{products.length} produtos</small></div></button>{categoryNames.map((category) => { const count = products.filter((p) => p.category === category).length; return <button type="button" key={category} className="category-card" onClick={() => onSelect(category)}><Package size={22} /><div><strong>{category}</strong><small>{count} {count === 1 ? 'produto' : 'produtos'}</small></div><span className="category-chevron">Ver →</span></button>})}</div> : <><div className="category-toolbar"><button type="button" className="back-category" onClick={() => onSelect('Todas as categorias')}>← Todas as categorias</button><strong>{selected}</strong><span>{visible.length} produtos</span></div><div className="product-list">{visible.length ? visible.map((p) => { const status = statusFor(p); return <div className="product-card" key={p.id}><div><strong>{p.name}</strong><small>{p.category} · {p.unit}</small></div><div className="stock-number"><b className={status.tone === 'critical' ? 'low' : status.tone === 'attention' ? 'attention' : ''}>{p.current}</b><small>{status.label} · mín. {p.minimum}</small></div><button className="icon-button" onClick={() => onEdit(p)} aria-label={`Editar ${p.name}`}>Editar</button></div>}) : <Empty text="Nenhum produto encontrado." />}</div></>}</> }

function StockCategoryCards({ products, selected, onSelect }: { products: Product[]; selected: string; onSelect: (category: string) => void }) { const grouped = Array.from(new Set(products.map((p) => p.category))).sort((a, b) => a.localeCompare(b, 'pt-BR')); const statusFor = (category: string) => { const items = products.filter((p) => p.category === category); if (items.some((p) => p.current <= p.minimum)) return { label: 'Crítico', tone: 'critical' }; if (items.some((p) => p.current <= p.minimum * 1.25)) return { label: 'Atenção', tone: 'attention' }; return { label: 'Normal', tone: 'normal' } }; return <div className="category-grid">{grouped.map((category) => { const status = statusFor(category); const count = products.filter((p) => p.category === category).length; return <button type="button" key={category} className={`category-card ${selected === category ? 'selected' : ''}`} onClick={() => onSelect(category)}><span className={`stock-status-dot ${status.tone}`} aria-label={`Estoque ${status.label}`} /><div><strong>{category}</strong><small>{count} {count === 1 ? 'produto' : 'produtos'}</small></div><span className={`stock-status ${status.tone}`}>{status.label}</span></button>})}</div> }

function CategoryMovementForm({ users, currentUserId, setCurrentUserId, type, products, category, selected, quantity, setCategory, setSelected, setQuantity, notes, setNotes, submit, onSelectProduct }: { users: StockUser[]; currentUserId: string; setCurrentUserId: (value: string) => void; type: 'Entrada' | 'Saída'; products: Product[]; category: string; selected: string; quantity: string; setCategory: (v: string) => void; setSelected: (v: string) => void; setQuantity: (v: string) => void; notes: string; setNotes: (v: string) => void; submit: (t: 'Entrada' | 'Saída') => void; onSelectProduct: (product: Product) => void }) { const categoryProducts = category ? products.filter((p) => p.category === category) : []; return <><PageTitle title={type === 'Entrada' ? 'Entrada de estoque' : 'Registrar saída'} subtitle="Escolha uma categoria para continuar" />{!category ? <StockCategoryCards products={products} selected={category} onSelect={setCategory} /> : <div className="category-flow"><button className="back-category" type="button" onClick={() => { setCategory(''); setSelected('') }}>← Todas as categorias</button><h2>{category}</h2><div className="category-products">{categoryProducts.map((p) => <button type="button" className={`category-product ${selected === p.id ? 'selected' : ''}`} key={p.id} onClick={() => { setSelected(p.id); setQuantity(''); onSelectProduct(p) }}><span><strong>{p.name}</strong><small>Estoque: {p.current} {p.unit} · Mínimo: {p.minimum}</small></span><b className={p.current <= p.minimum ? 'critical-text' : ''}>{p.current}</b></button>)}</div></div>}</> }

function MovementForm({ type, products, category, selected, quantity, setCategory, setSelected, setQuantity, submit }: { type: 'Entrada' | 'Saída'; products: Product[]; category: string; selected: string; quantity: string; setCategory: (v: string) => void; setSelected: (v: string) => void; setQuantity: (v: string) => void; submit: (t: 'Entrada' | 'Saída') => void }) { const product = products.find((p) => p.id === selected); const categories = Array.from(new Set(products.map((p) => p.category))).sort((a, b) => a.localeCompare(b, 'pt-BR')); const categoryProducts = category ? products.filter((p) => p.category === category) : []; return <><PageTitle title={type === 'Entrada' ? 'Entrada de estoque' : 'Registrar saída'} subtitle={type === 'Entrada' ? 'Adicione produtos recebidos' : 'Atualize o consumo do bar'} /><div className="movement-form"><label>Categoria<select className="touch-select" value={category} onChange={(e) => setCategory(e.target.value)}><option value="">Selecione uma categoria</option>{categories.map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label>Produto<select className="touch-select" value={selected} disabled={!category} onChange={(e) => setSelected(e.target.value)}><option value="">{category ? 'Selecione um produto' : 'Escolha uma categoria primeiro'}</option>{categoryProducts.map((p) => <option key={p.id} value={p.id}>{p.name} · {p.current} {p.unit}</option>)}</select></label><label>Quantidade<input type="number" min="1" inputMode="numeric" placeholder="0" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label>{product && <div className="current-stock">Estoque atual <b>{product.current} {product.unit}</b></div>}<button className="submit-large" onClick={() => submit(type)}>{type === 'Entrada' ? 'Confirmar entrada' : 'Confirmar saída'}</button></div></> }
function CategoryPurchase({ products, movements, category, setCategory, quantities, setQuantities, confirm }: { products: Product[]; movements: Movement[]; category: string; setCategory: (value: string) => void; quantities: Record<string, number>; setQuantities: (value: Record<string, number>) => void; confirm: (items: Array<{ productId: string; quantity: number }>) => void }) { const suggestions = products.map((p) => { const consumed = movements.filter((m) => m.productId === p.id && m.type === 'Saída').reduce((sum, m) => sum + m.quantity, 0); return { ...p, consumed, suggestion: Math.max(0, p.ideal - p.current) } }).filter((p) => p.suggestion > 0 || p.consumed > 0); const selectedProducts = category ? suggestions.filter((p) => p.category === category) : []; const valueFor = (p: Product & { suggestion: number }) => quantities[p.id] ?? p.suggestion; return <><PageTitle title="Sugestão de compra" subtitle="Escolha uma categoria para revisar as compras" />{!category ? <StockCategoryCards products={suggestions} selected="" onSelect={setCategory} /> : <div className="category-flow"><button className="back-category" type="button" onClick={() => setCategory('')}>← Todas as categorias</button><h2>{category}</h2><div className="purchase-list">{selectedProducts.length ? selectedProducts.map((p) => <div className="purchase-row" key={p.id}><div><strong>{p.name}</strong><small>Estoque atual: {p.current} · consumo semanal: {p.consumed}</small></div><input aria-label={`Quantidade para comprar de ${p.name}`} type="number" min="0" value={valueFor(p)} onChange={(e) => setQuantities({ ...quantities, [p.id]: Number(e.target.value) })} /><span>{p.unit}</span></div>) : <Empty text="Nenhuma compra sugerida nesta categoria." />}</div>{selectedProducts.length > 0 && <button className="submit-large" onClick={() => confirm(selectedProducts.map((p) => ({ productId: p.id, quantity: valueFor(p) })))}>Criar pedido de compra</button>}</div>}</> }

function Purchase({ products, movements, category, setCategory, quantities, setQuantities, confirm }: { products: Product[]; movements: Movement[]; category: string; setCategory: (value: string) => void; quantities: Record<string, number>; setQuantities: (value: Record<string, number>) => void; confirm: (items: Array<{ productId: string; quantity: number }>) => void }) { const categoryOptions = Array.from(new Set(products.map((p) => p.category))).sort((a, b) => a.localeCompare(b, 'pt-BR')); const suggestions = products.map((p) => { const consumed = movements.filter((m) => m.productId === p.id && m.type === 'Saída').reduce((sum, m) => sum + m.quantity, 0); return { ...p, consumed, suggestion: Math.max(0, p.ideal - p.current) } }).filter((p) => (category === 'Todas as categorias' || p.category === category) && (p.suggestion > 0 || p.consumed > 0)).sort((a, b) => b.suggestion - a.suggestion); const valueFor = (p: Product & { suggestion: number }) => quantities[p.id] ?? p.suggestion; return <><PageTitle title="Sugestão de compra" subtitle="Baseada no consumo dos últimos 7 dias" /><div className="purchase-note">Revise as quantidades antes de confirmar o pedido.</div><div className="purchase-filter"><label htmlFor="purchase-category">Categoria</label><select id="purchase-category" className="touch-select" value={category} onChange={(e) => setCategory(e.target.value)}><option>Todas as categorias</option>{categoryOptions.map((item) => <option key={item}>{item}</option>)}</select></div><div className="purchase-list">{suggestions.length ? suggestions.map((p) => <div className="purchase-row" key={p.id}><div><strong>{p.name}</strong><small>Estoque atual: {p.current} · consumo semanal: {p.consumed}</small></div><input aria-label={`Quantidade para comprar de ${p.name}`} type="number" min="0" value={valueFor(p)} onChange={(e) => setQuantities({ ...quantities, [p.id]: Number(e.target.value) })} /><span>{p.unit}</span></div>) : <Empty text="Nenhuma compra sugerida nesta categoria." />}<button className="primary full" onClick={() => confirm(suggestions.map((p) => ({ productId: p.id, quantity: valueFor(p) })))}>Confirmar pedido</button></div></> }

function Orders({ orders, products, selectedOrder, setSelectedOrder }: { orders: PurchaseOrder[]; products: Product[]; selectedOrder: string | null; setSelectedOrder: (id: string | null) => void }) { const selected = orders.find((order) => order.id === selectedOrder); return <><PageTitle title="Pedidos de compra" subtitle={`${orders.length} pedidos registrados`} />{selected ? <section className="purchase-list"><button className="secondary" onClick={() => setSelectedOrder(null)}>Voltar aos pedidos</button><h2>Pedido #{selected.id.slice(0, 8).toUpperCase()}</h2><p>{new Date(selected.createdAt).toLocaleString('pt-BR')} · {selected.status}</p>{selected.items.map((item) => <div className="purchase-row" key={item.id}><div><strong>{products.find((p) => p.id === item.productId)?.name ?? 'Produto'}</strong></div><b>{item.quantity}</b></div>)}</section> : <div className="purchase-list">{orders.length ? orders.map((order) => <button className="history-row" key={order.id} onClick={() => setSelectedOrder(order.id)}><div><strong>Pedido #{order.id.slice(0, 8).toUpperCase()}</strong><small>{new Date(order.createdAt).toLocaleDateString('pt-BR')}</small></div><span>{order.status} · {order.items.length} itens</span></button>) : <Empty text="Nenhum pedido de compra criado ainda." />}</div>}</> }
function ShoppingList({ products, category, setCategory, quantities, setQuantities, confirm, purchaseDays, setPurchaseDays }: { products: Array<Product & { suggested: number }>; category: string; setCategory: (value: string) => void; quantities: Record<string, number>; setQuantities: (value: Record<string, number>) => void; confirm: (items: Array<{ productId: string; quantity: number }>) => void; purchaseDays: number[]; setPurchaseDays: (days: number[]) => void }) { const days = [{ value: 1, label: 'Segunda-feira' }, { value: 2, label: 'Terça-feira' }, { value: 3, label: 'Quarta-feira' }, { value: 4, label: 'Quinta-feira' }, { value: 5, label: 'Sexta-feira' }, { value: 6, label: 'Sábado' }, { value: 7, label: 'Domingo' }]; const categories = Array.from(new Set(products.map((p) => p.category))).sort((a, b) => a.localeCompare(b, 'pt-BR')); const visible = category === 'Todas as categorias' ? products : products.filter((p) => p.category === category); const valueFor = (p: Product & { suggested: number }) => quantities[p.id] ?? p.suggested; const toggleDay = (day: number) => setPurchaseDays(purchaseDays.includes(day) ? purchaseDays.filter((item) => item !== day) : [...purchaseDays, day].sort()); return <><PageTitle title="Lista de compras" subtitle="Reposição automática até o estoque desejado" /><section className="shopping-settings"><div className="section-heading"><div><h2>Dias de compra</h2><p>O dashboard destaca a lista nestes dias.</p></div><CalendarDays size={20} /></div><div className="day-options">{days.map((day) => <button type="button" key={day.value} className={purchaseDays.includes(day.value) ? 'selected' : ''} onClick={() => toggleDay(day.value)}>{day.label.replace('-feira', '')}</button>)}</div></section><div className="purchase-filter"><label htmlFor="purchase-category">Filtrar por categoria</label><select id="purchase-category" className="touch-select" value={category} onChange={(e) => setCategory(e.target.value)}><option>Todas as categorias</option>{categories.map((item) => <option key={item}>{item}</option>)}</select></div>{visible.length ? <div className="shopping-table"><div className="shopping-table-head"><span>Produto</span><span>Atual</span><span>Mínimo</span><span>Desejado</span><span>Comprar</span></div>{visible.map((p) => <div className="shopping-table-row" key={p.id}><div><strong>{p.name}</strong><small>{p.unit}</small></div><span>{p.current}</span><span>{p.minimum}</span><span>{p.ideal}</span><label><span className="sr-only">Quantidade para comprar de {p.name}</span><input type="number" min="0" value={valueFor(p)} onChange={(e) => setQuantities({ ...quantities, [p.id]: Number(e.target.value) })} /></label></div>)}</div> : <Empty text="Nenhum produto precisa de reposição no momento." />} {visible.length > 0 && <button className="submit-large" onClick={() => confirm(visible.map((p) => ({ productId: p.id, quantity: valueFor(p) })))}>Enviar pedido de compra</button>}</> }

function QuickMovementModal({ type, product, quantity, setQuantity, notes, setNotes, saving, submit, close }: { type: 'Entrada' | 'Saída'; product: Product; quantity: string; setQuantity: (value: string) => void; notes: string; setNotes: (value: string) => void; saving: boolean; submit: (type: 'Entrada' | 'Saída') => void; close: () => void }) { return <div className="modal-backdrop quick-movement-backdrop" role="presentation" style={{ position: 'fixed', inset: 0, zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, background: 'rgba(30, 27, 22, .58)' }} onMouseDown={(event) => { if (event.target === event.currentTarget) close() }}><section className="modal quick-movement-modal" role="dialog" aria-modal="true" aria-labelledby="quick-movement-title" style={{ position: 'relative', zIndex: 201, display: 'flex', flexDirection: 'column', width: 'min(420px, calc(100vw - 32px))', margin: 'auto', padding: 28, background: '#fff', border: '1px solid rgba(30, 27, 22, .14)', borderRadius: 18, boxShadow: '0 24px 80px rgba(30, 27, 22, .3)' }} onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><span className="modal-kicker">{type === 'Entrada' ? 'Entrada de estoque' : 'Registrar saída'}</span><h2 id="quick-movement-title">{product.name}</h2></div><button className="modal-close" onClick={close} aria-label="Fechar ação"><X size={21} /></button></div><div className="modal-form-stack"><div className="quick-product-field"><span>Produto selecionado</span><strong>{product.name}</strong></div><div className="quick-stock"><span>Estoque atual</span><strong>{product.current} {product.unit}</strong></div><label className="quick-quantity-label">Quantidade<input autoFocus className="quick-quantity-input" type="number" min="1" inputMode="numeric" placeholder="0" value={quantity} onChange={(event) => setQuantity(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.nativeEvent.isComposing && event.keyCode !== 229) submit(type) }} /></label><label className="quick-notes-label">Observação<textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder={type === 'Entrada' ? 'Ex.: Compra fornecedor ou reposição semanal' : 'Ex.: Venda, uso interno ou perda'} required /></label><div className="quick-responsible"><span>Responsável</span><strong>Usuário conectado</strong></div><div className="quick-form-actions"><button className="submit-large quick-submit" disabled={saving} onClick={() => submit(type)}>{saving ? 'Salvando...' : type === 'Entrada' ? 'Confirmar entrada' : 'Confirmar saída'}</button><button className="secondary cancel-edit" onClick={close}>Cancelar</button></div></div></section></div> }

function ProductModal({ product, setProduct, save, remove }: { product: Product; setProduct: (p: Product | null) => void; save: () => void; remove?: () => void }) { const update = (key: keyof Product, value: string | number) => setProduct({ ...product, [key]: ['current', 'minimum', 'ideal'].includes(key) ? Number(value) : value }); const close = () => setProduct(null); return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) close() }}><section className="modal edit-modal" role="dialog" aria-modal="true" aria-labelledby="edit-product-title" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><span className="modal-kicker">Cadastro de estoque</span><h2 id="edit-product-title">{remove ? 'Editar produto' : 'Novo produto'}</h2></div><button className="modal-close" onClick={close} aria-label="Fechar edição"><X size={21} /></button></div><div className="edit-fields">{[['name', 'Nome do produto'], ['category', 'Categoria'], ['unit', 'Unidade'], ['current', 'Estoque atual'], ['minimum', 'Estoque mínimo'], ['ideal', 'Estoque ideal']].map(([key, label]) => <label key={key}>{label}{key === 'category' ? <select value={product[key as keyof Product] as string} onChange={(e) => update(key as keyof Product, e.target.value)}>{categories.map((c) => <option key={c}>{c}</option>)}</select> : <input type={key === 'name' || key === 'unit' ? 'text' : 'number'} min={key === 'name' || key === 'unit' ? undefined : 0} inputMode={key === 'name' || key === 'unit' ? 'text' : 'numeric'} value={product[key as keyof Product] as string | number} onChange={(e) => update(key as keyof Product, e.target.value)} />}</label>)}</div><div className="edit-actions"><button className="submit-large" onClick={save}>Salvar alterações</button><button className="secondary cancel-edit" onClick={close}>Cancelar</button>{remove && <button className="delete-button" onClick={remove}><Trash2 size={16} /> Remover produto</button>}</div></section></div> }
